def Strongest_Extension(class_name: str, extensions: List[str]) -> str:
    best_extension = None
    best_strength = float('-inf')

    for ext in extensions:
        cap = 0
        sm = 0
        for char in ext:
            if char.isupper():
                cap += 1
            elif char.islower():
                sm += 1
        strength = cap - sm

        if strength > best_strength:
            best_strength = strength
            best_extension = ext

    return f"{class_name}.{best_extension}"

